import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Tentacle Awards","description":"","frontmatter":{"title":"Tentacle Awards","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["社区动态","会议纪要","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Tentacle_Awards.md","filePath":"posts/2026/Tentacle_Awards.md","lastUpdated":null}'),s={name:"posts/2026/Tentacle_Awards.md"};function p(n,e,l,d,i,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="_2026-tentacle-awards-颁奖典礼纪要" tabindex="-1">2026 Tentacle Awards 颁奖典礼纪要 <a class="header-anchor" href="#_2026-tentacle-awards-颁奖典礼纪要" aria-label="Permalink to &quot;2026 Tentacle Awards 颁奖典礼纪要&quot;">​</a></h2><p>本次会议为 2026 年 Ceph 社区 Tentacle Awards 颁奖典礼，旨在表彰对 Ceph 项目做出杰出贡献的社区成员。</p><h3 id="tentacle-award-获奖者" tabindex="-1">Tentacle Award 获奖者 <a class="header-anchor" href="#tentacle-award-获奖者" aria-label="Permalink to &quot;Tentacle Award 获奖者&quot;">​</a></h3><p><strong>Mark Nelson</strong></p><p>Mark Nelson 长期担任 Ceph 性能技术负责人（PTL），深度参与了 Ceph 性能优化的方方面面，其贡献已难以与 Ceph 性能本身区分开来。他在 Ceph 项目上耕耘多年，留下了不可磨灭的印记，目前继续担任 Crimson 项目的首席架构师。</p><p>颁奖过程中，Mark 因网络音频故障一度无法发言，典礼结束时终于接通，他表达了对社区的深切感谢：&quot;我非常非常感激，能看到这里所有构建这些东西的面孔，真的是一种荣誉。&quot;</p><p><strong>Yuri Weinstein</strong></p><p>Yuri Weinstein 长期在 Ceph SE 团队任职，是著名的测试工程师及软件贡献者，尤其在 Ceph 开源项目的 release 管理与测试编排方面贡献卓著。他从公园发来视频致辞，表示深感荣幸并期待未来继续贡献。</p><h3 id="octopus-award-获奖者-历史-ptl-特别表彰" tabindex="-1">Octopus Award 获奖者（历史 PTL 特别表彰） <a class="header-anchor" href="#octopus-award-获奖者-历史-ptl-特别表彰" aria-label="Permalink to &quot;Octopus Award 获奖者（历史 PTL 特别表彰）&quot;">​</a></h3><p>本届典礼还新设了针对早期 PTL 的专项表彰，补授予那些在 Tentacle Award 设立之前便已卸任、从未获此殊荣的历史贡献者。</p><p><strong>Yehuda Sadeh-Weinraub（RGW 原作者）</strong></p><p>Yehuda 是 RGW（RADOS Gateway）的原始作者，为 Ceph 奠定了 S3 协议生态的根基，推动 Ceph 成为 PB 级别对象存储领域的领导者。他在致辞中特别感谢 Sage Weil 创立社区并重视社区文化：&quot;他始终坚信社区的重要性，他一如既往地是对的。&quot;</p><p>目前 Yehuda 在 Ubiquiti Networks 担任计算副总裁，主持人调侃道&quot;不要太惊讶如果你的 Wi-Fi 路由器哪天开始跑 Ceph&quot;。</p><p><strong>Sam Just（RADOS 原 PTL）</strong></p><p>Sam Just 接过 Sage Weil 对 Ceph 核心层 RADOS 的责任，并一直以强烈的使命感承担最棘手的技术难题，包括近期的 Python GIL 相关问题。他以团队中最具合作精神著称，致辞中表达了对这个社区的深厚感情。</p><p><strong>Greg Farnum</strong></p><p>社区流传着一句话来形容 Greg 的价值：&quot;一个产品不能有超过一个 Greg，但也不能少于一个 Greg。&quot; Greg 以直言不讳、敢于指出问题著称，是团队的&quot;良知&quot;所在。他还在 stretch clustering 实现中展现了跨领域能力，以超乎预期的速度完成了 RADOS 层的相关改动。Greg 表示，加入 Ceph 社区是他职业生涯的第一份工作，见证社区从一个热情用户成长为拥有数百人邮件列表、服务众多企业客户的大型项目，是莫大的荣幸。</p><p><strong>Josh Durgin（RBD 原 PTL）</strong></p><p>Josh 作为 RBD（RADOS Block Device）的原始技术负责人，帮助 Ceph 打入了 OpenStack 这一最关键的早期市场，且以高效、温和、低调的风格赢得了社区的广泛尊重。他在致辞中感谢了早期团队成员与整个社区，认为社区的协作文化是 Ceph 独特之处所在。</p><h3 id="花絮" tabindex="-1">花絮 <a class="header-anchor" href="#花絮" aria-label="Permalink to &quot;花絮&quot;">​</a></h3><p>主持人在典礼结束时幽默地指出，获奖者中出现了&quot;加利福尼亚 vs. 加拿大&quot;的三三对阵局面，并期待未来这一&quot;竞争&quot;如何演变。典礼尽量安排在伦敦时间较晚进行，以兼顾不同时区的与会者。</p>',21)])])}const _=a(s,[["render",p]]);export{h as __pageData,_ as default};
